CREATE OR REPLACE FUNCTION public.rsc_check_loss_first_correction_plan_0159(checked_correction uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE correction public.stock_loss_correction_executions%ROWTYPE;
    inverse public.stock_loss_disposition_reversals%ROWTYPE; decision public.stock_loss_correction_decisions%ROWTYPE;
    root public.stock_loss_dispositions%ROWTYPE; parent public.stock_operation_orders%ROWTYPE;
    tx public.inventory_transactions%ROWTYPE; source public.stock_accounts%ROWTYPE; target public.stock_accounts%ROWTYPE;
    custody public.custody_assignments%ROWTYPE; policy public.material_inventory_policies%ROWTYPE;
    observed bigint; cutoff bigint; source_amount numeric; target_amount numeric; source_version bigint; target_version bigint;
    serial_ids jsonb; holds jsonb; share jsonb; recorded jsonb; fingerprint jsonb; dimensions jsonb;
    expected jsonb; command jsonb; identifier uuid; current_sn record; new_target boolean; target_id uuid;
    movement text; effective_from_text text; effective_to_text text;
BEGIN
    SELECT * INTO correction FROM public.stock_loss_correction_executions WHERE id=checked_correction;
    SELECT * INTO inverse FROM public.stock_loss_disposition_reversals WHERE id=correction.reversal_id;
    SELECT * INTO decision FROM public.stock_loss_correction_decisions WHERE id=correction.correction_decision_id;
    SELECT * INTO root FROM public.stock_loss_dispositions WHERE id=correction.root_disposition_id;
    IF correction.id IS NULL OR root.id IS NULL OR inverse.id IS NULL OR decision.id IS NULL
       OR inverse.root_disposition_id IS DISTINCT FROM root.id
       OR decision.root_disposition_id IS DISTINCT FROM root.id
       OR decision.reversal_id IS DISTINCT FROM inverse.id
       OR correction.disposition NOT IN ('restore_available','convert_used','convert_damaged')
       OR decision.disposition IS DISTINCT FROM correction.disposition THEN
        RAISE EXCEPTION 'later correction exact account plan required' USING ERRCODE='23514'; END IF;
    PERFORM public.rsc_check_loss_first_inverse_plan_0159(inverse.id);
    SELECT COALESCE(max(ledger_cursor),0) INTO observed FROM public.inventory_transactions;
    SELECT * INTO parent FROM public.stock_operation_orders WHERE id=root.operation_id;
    SELECT * INTO tx FROM public.inventory_transactions WHERE id=correction.posting_transaction_id;
    SELECT * INTO source FROM public.stock_accounts WHERE id=correction.source_account_id;
    SELECT * INTO target FROM public.stock_accounts WHERE id=correction.target_account_id;
    cutoff:=tx.ledger_cursor-1;
    IF source.id IS NULL OR target.id IS NULL OR source.availability_bucket IS DISTINCT FROM 'frozen'
       OR target.availability_bucket IS DISTINCT FROM 'available' OR source.id IS DISTINCT FROM root.source_account_id
       OR correction.quantity IS DISTINCT FROM root.quantity OR source.id=target.id
       OR source.owner_org_id IS DISTINCT FROM target.owner_org_id OR source.location_id IS DISTINCT FROM target.location_id
       OR source.custodian_person_id IS DISTINCT FROM target.custodian_person_id
       OR source.custodian_person_id IS DISTINCT FROM parent.requester_id OR source.material_id IS DISTINCT FROM target.material_id
       OR source.lot_id IS DISTINCT FROM target.lot_id OR target.created_at IS NULL OR target.created_at>correction.created_at
       OR target.condition_code IS DISTINCT FROM (CASE correction.disposition WHEN 'restore_available' THEN source.condition_code
           WHEN 'convert_used' THEN 'used' ELSE 'damaged' END) THEN
        RAISE EXCEPTION '0159 exact historical correction accounts required' USING ERRCODE='23514'; END IF;
    SELECT * INTO custody FROM public.custody_assignments WHERE location_id=source.location_id
        AND valid_from<=correction.created_at AND (valid_to IS NULL OR valid_to>correction.created_at);
    IF custody.id IS DISTINCT FROM correction.custody_assignment_id OR custody.custodian_person_id IS DISTINCT FROM parent.requester_id
       OR (SELECT count(*) FROM public.custody_assignments WHERE location_id=source.location_id
            AND valid_from<=correction.created_at AND (valid_to IS NULL OR valid_to>correction.created_at))<>1 THEN
        RAISE EXCEPTION '0159 unique historical correction custody required' USING ERRCODE='23514'; END IF;
    SELECT COALESCE(sum(CASE WHEN m.to_account_id=source.id THEN m.quantity ELSE -m.quantity END),0),count(DISTINCT t.id)
        INTO source_amount,source_version FROM public.inventory_movements m JOIN public.inventory_transactions t ON t.id=m.transaction_id
        WHERE t.status='posted' AND t.ledger_cursor<=cutoff AND source.id IN (m.from_account_id,m.to_account_id);
    SELECT COALESCE(sum(CASE WHEN m.to_account_id=target.id THEN m.quantity ELSE -m.quantity END),0),count(DISTINCT t.id)
        INTO target_amount,target_version FROM public.inventory_movements m JOIN public.inventory_transactions t ON t.id=m.transaction_id
        WHERE t.status='posted' AND t.ledger_cursor<=cutoff AND target.id IN (m.from_account_id,m.to_account_id);
    new_target:=target.created_at=correction.created_at;
    IF new_target THEN
        dimensions:=jsonb_build_object('owner_org_id',target.owner_org_id::text,'location_id',target.location_id::text,
            'custodian_person_id',target.custodian_person_id::text,'material_id',target.material_id::text,
            'lot_id',target.lot_id::text,'condition_code',target.condition_code,'availability_bucket',target.availability_bucket);
        target_id:=rsc_loss_uuid_0159.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8'::uuid,
            'rsc:stock-loss-disposition-account:v1:'||encode(sha256(convert_to(
                public.rsc_canonical_reconciliation_json_0026(dimensions),'UTF8')),'hex'));
        IF target.id IS DISTINCT FROM target_id OR target_amount<>0 OR target_version<>0 THEN
            RAISE EXCEPTION '0159 exact newly created correction account required' USING ERRCODE='23514'; END IF;
    END IF;
    IF source_amount<correction.quantity OR target_amount<0 THEN
        RAISE EXCEPTION '0159 sufficient historical correction balances required' USING ERRCODE='23514'; END IF;
    SELECT COALESCE(jsonb_agg(serial_id::text ORDER BY serial_id::text),'[]'::jsonb) INTO serial_ids
        FROM public.stock_operation_serials WHERE line_id=root.line_id;
    holds:=public.rsc_loss_hold_projection_0159(source.id,cutoff);
    SELECT value INTO share FROM jsonb_array_elements(holds->'lines') WHERE value->>'line_id'=root.line_id::text;
    IF share IS NULL OR share->'active_execution_id' IS DISTINCT FROM 'null'::jsonb
       OR share->>'pending_reversal_id' IS DISTINCT FROM inverse.id::text
       OR share->>'frozen_quantity' IS DISTINCT FROM to_char(root.quantity,'FM999999999999990.000')
       OR share->'frozen_serial_ids' IS DISTINCT FROM serial_ids THEN
        RAISE EXCEPTION '0159 exact pre-correction restored share required' USING ERRCODE='23514'; END IF;
    FOR identifier IN SELECT value::uuid FROM jsonb_array_elements_text(serial_ids) LOOP
        SELECT m.id,m.to_account_id,m.external_boundary_code,t.movement_type INTO current_sn
            FROM public.inventory_movement_serials s JOIN public.inventory_movements m ON m.id=s.movement_id
            JOIN public.inventory_transactions t ON t.id=m.transaction_id WHERE s.serial_id=identifier
                AND s.transaction_id=t.id AND t.status='posted' AND t.ledger_cursor<=cutoff
            ORDER BY t.ledger_cursor DESC,m.line_no DESC LIMIT 1;
        IF current_sn.id IS DISTINCT FROM inverse.posting_movement_id OR current_sn.to_account_id IS DISTINCT FROM source.id
           OR current_sn.external_boundary_code IS NOT NULL OR current_sn.movement_type IS DISTINCT FROM 'reversal'
           OR NOT EXISTS(SELECT 1 FROM public.inventory_serials WHERE id=identifier AND material_id=source.material_id
                AND lot_id IS NOT DISTINCT FROM source.lot_id) THEN
            RAISE EXCEPTION '0159 exact active correction serial lineage required' USING ERRCODE='23514'; END IF;
    END LOOP;
    SELECT * INTO policy FROM public.material_inventory_policies WHERE material_id=source.material_id
        AND effective_from<=correction.created_at AND (effective_to IS NULL OR effective_to>correction.created_at);
    IF policy.id IS NULL OR (SELECT count(*) FROM public.material_inventory_policies WHERE material_id=source.material_id
            AND effective_from<=correction.created_at AND (effective_to IS NULL OR effective_to>correction.created_at))<>1
       OR policy.tracking_mode NOT IN ('none','lot','serial','lot_and_serial') OR policy.quantity_scale NOT BETWEEN 0 AND 3
       OR correction.quantity<>trunc(correction.quantity,policy.quantity_scale)
       OR (NOT policy.allow_fraction AND correction.quantity<>trunc(correction.quantity))
       OR (policy.tracking_mode IN ('none','serial') AND source.lot_id IS NOT NULL)
       OR (policy.tracking_mode IN ('lot','lot_and_serial') AND source.lot_id IS NULL)
       OR (policy.tracking_mode IN ('serial','lot_and_serial') AND jsonb_array_length(serial_ids)<>correction.quantity)
       OR (policy.tracking_mode IN ('none','lot') AND serial_ids<>'[]'::jsonb) THEN
        RAISE EXCEPTION '0159 exact historical correction tracking policy required' USING ERRCODE='23514'; END IF;
    effective_from_text:=to_char(policy.effective_from AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS')||
        CASE WHEN extract(microseconds FROM policy.effective_from)::bigint % 1000000=0 THEN ''
            ELSE '.'||to_char(policy.effective_from AT TIME ZONE 'UTC','US') END||'+00:00';
    effective_to_text:=CASE WHEN policy.effective_to IS NULL THEN NULL ELSE
        to_char(policy.effective_to AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS')||
        CASE WHEN extract(microseconds FROM policy.effective_to)::bigint % 1000000=0 THEN ''
            ELSE '.'||to_char(policy.effective_to AT TIME ZONE 'UTC','US') END||'+00:00' END;
    recorded:=correction.plan_jsonb->'policy_fingerprint';
    fingerprint:=jsonb_build_array(jsonb_build_array(source.material_id::text,policy.id::text,policy.tracking_mode,
        policy.quantity_scale,policy.allow_fraction,effective_from_text,recorded->0->6));
    IF jsonb_typeof(recorded) IS DISTINCT FROM 'array' OR jsonb_array_length(recorded)<>1
       OR jsonb_typeof(recorded->0) IS DISTINCT FROM 'array' OR jsonb_array_length(recorded->0)<>7
       OR (recorded->0->6<>'null'::jsonb AND recorded->0->6 IS DISTINCT FROM to_jsonb(effective_to_text))
       OR public.rsc_canonical_reconciliation_json_0026(recorded) IS DISTINCT FROM public.rsc_canonical_reconciliation_json_0026(fingerprint) THEN
        RAISE EXCEPTION '0159 exact correction policy fingerprint required' USING ERRCODE='23514'; END IF;

    movement:=CASE decision.disposition WHEN 'restore_available' THEN 'unfreeze' ELSE 'status_change' END;
    expected:=jsonb_build_object('schema_version','1.0','stage','correction_execution_plan','intent',correction.command_jsonb->'intent',
        'actor_user_id',correction.actor_user_id,'actor_person_id',correction.actor_person_id::text,'authorization_version',correction.authorization_version,
        'root_disposition_id',root.id::text,'reversal_id',inverse.id::text,'correction_decision_id',decision.id::text,
        'disposition',decision.disposition,'source_account_id',source.id::text,'target_account_id',target.id::text,
        'source_condition',source.condition_code,'target_condition',target.condition_code,'target_requires_creation',new_target,
        'custody_assignment_id',custody.id::text,'quantity',to_char(correction.quantity,'FM999999999999990.000'),
        'serial_ids',serial_ids,'movement_type',movement,'ledger_cursor',cutoff,
        'source_balance_quantity',to_char(source_amount,'FM999999999999990.000'),'source_balance_version',source_version,
        'target_balance_quantity',to_char(target_amount,'FM999999999999990.000'),'target_balance_version',target_version,
        'frozen_holds_before',holds,'policy_fingerprint',fingerprint);
    IF public.rsc_canonical_reconciliation_json_0026(correction.plan_jsonb) IS DISTINCT FROM public.rsc_canonical_reconciliation_json_0026(expected)
       OR correction.plan_hash IS DISTINCT FROM encode(sha256(convert_to(public.rsc_canonical_reconciliation_json_0026(expected),'UTF8')),'hex') THEN
        RAISE EXCEPTION '0159 full historical correction plan mismatch' USING ERRCODE='23514'; END IF;
    command:=jsonb_build_object('operation','post','actor',jsonb_build_object('authorization_version',correction.authorization_version,
        'person_id',correction.actor_person_id::text,'user_id',correction.actor_user_id),'command',jsonb_build_object(
        'effective_at',to_char(correction.created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
        'movement_type',movement,'posting_key','stock-loss:correct_loss:'||correction.id::text||':'||correction.idempotency_key_hash,
        'source_document_id',correction.id::text,'source_document_type','stock_loss_correction_execution',
        'transaction_no','INV-LOSS-CORR-'||upper(substr(correction.idempotency_key_hash,1,20)),
        'movements',jsonb_build_array(jsonb_build_object('external_boundary_code',NULL,'from_account_id',source.id::text,
            'to_account_id',target.id::text,'quantity',trim_scale(correction.quantity)::text,'serial_ids',serial_ids))));
    IF tx.posting_key IS DISTINCT FROM command->'command'->>'posting_key'
       OR tx.transaction_no IS DISTINCT FROM command->'command'->>'transaction_no'
       OR tx.request_hash IS DISTINCT FROM encode(sha256(convert_to(public.rsc_canonical_reconciliation_json_0026(command),'UTF8')),'hex')
       OR observed<>(SELECT COALESCE(max(ledger_cursor),0) FROM public.inventory_transactions) THEN
        RAISE EXCEPTION '0159 canonical correction posting command mismatch' USING ERRCODE='23514'; END IF;
    RETURN expected;
END;
