CREATE OR REPLACE FUNCTION public.rsc_check_loss_history_graph_0159(checked_root uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE pending uuid[]:=ARRAY[checked_root]; visited uuid[]:=ARRAY[]::uuid[];
    inverse_ids uuid[]:=ARRAY[]::uuid[]; correction_ids uuid[]:=ARRAY[]::uuid[];
    queue_index integer:=1; identifier uuid; ancestor uuid; cursor_item bigint; inverse_id uuid; correction_id uuid;
    root public.stock_loss_dispositions%ROWTYPE; projected jsonb; piece jsonb;
    observed bigint; heads jsonb; final_heads jsonb;
BEGIN
    IF checked_root IS NULL OR checked_root='00000000-0000-0000-0000-000000000000'::uuid THEN
        RAISE EXCEPTION '0159 normal history root required' USING ERRCODE='23514'; END IF;
    SELECT COALESCE(max(ledger_cursor),0) INTO observed FROM public.inventory_transactions;
    SELECT COALESCE(jsonb_agg(jsonb_build_array(stream_key,version,last_event_id::text,last_hash) ORDER BY stream_key),'[]'::jsonb)
        INTO heads FROM public.audit_chain_heads WHERE stream_key IN ('inventory','material_request');
    WHILE queue_index<=cardinality(pending) LOOP
        identifier:=pending[queue_index];queue_index:=queue_index+1;
        SELECT * INTO root FROM public.stock_loss_dispositions WHERE id=identifier;
        IF root.id IS NULL THEN
            RAISE EXCEPTION '0159 retained loss root required' USING ERRCODE='23514'; END IF;
        IF root.disposition IN ('restore_available','convert_used','convert_damaged') THEN
            PERFORM public.rsc_check_loss_versioned_normal_original_0159(root.id);
        ELSIF root.disposition='return_to_region' THEN
            IF EXISTS(SELECT 1 FROM public.stock_loss_disposition_reversals WHERE root_disposition_id=root.id)
               OR EXISTS(SELECT 1 FROM public.stock_loss_correction_decisions WHERE root_disposition_id=root.id)
               OR EXISTS(SELECT 1 FROM public.stock_loss_correction_executions WHERE root_disposition_id=root.id) THEN
                RAISE EXCEPTION '0159 dedicated return compensation proof required' USING ERRCODE='23514'; END IF;
            PERFORM public.rsc_check_loss_return_0152(root.id,false);
        ELSE
            RAISE EXCEPTION '0159 dedicated scrap history proof required' USING ERRCODE='23514';
        END IF;
        PERFORM public.rsc_check_loss_upstream_history_0159(root.id);
        FOR inverse_id IN SELECT id FROM public.stock_loss_disposition_reversals
                WHERE root_disposition_id=root.id ORDER BY id LOOP
            PERFORM public.rsc_check_loss_first_inverse_plan_0159(inverse_id);
            inverse_ids:=array_append(inverse_ids,inverse_id);
        END LOOP;
        FOR correction_id IN SELECT id FROM public.stock_loss_correction_executions
                WHERE root_disposition_id=root.id ORDER BY id LOOP
            PERFORM public.rsc_check_loss_first_correction_plan_0159(correction_id);
            correction_ids:=array_append(correction_ids,correction_id);
        END LOOP;
        -- An inverse or correction may occur after another original report.
        -- Its own earlier holds are dependencies too, even when they were not
        -- present at this root's first posting.
        FOR cursor_item IN SELECT ledger_cursor FROM public.inventory_transactions
            WHERE id=root.posting_transaction_id OR id IN (
                SELECT posting_transaction_id FROM public.stock_loss_disposition_reversals WHERE root_disposition_id=root.id
                UNION SELECT posting_transaction_id FROM public.stock_loss_correction_executions WHERE root_disposition_id=root.id)
            ORDER BY ledger_cursor LOOP
            projected:=public.rsc_loss_hold_projection_0159(root.source_account_id,cursor_item-1);
            FOR piece IN SELECT value FROM jsonb_array_elements(projected->'lines') LOOP
                ancestor:=(piece->>'root_disposition_id')::uuid;
                IF ancestor IS NOT NULL AND NOT ancestor=ANY(pending) THEN
                    pending:=array_append(pending,ancestor);
                END IF;
            END LOOP;
        END LOOP;
        visited:=array_append(visited,root.id);
    END LOOP;
    SELECT COALESCE(jsonb_agg(jsonb_build_array(stream_key,version,last_event_id::text,last_hash) ORDER BY stream_key),'[]'::jsonb)
        INTO final_heads FROM public.audit_chain_heads WHERE stream_key IN ('inventory','material_request');
    IF final_heads IS DISTINCT FROM heads OR observed<>(SELECT COALESCE(max(ledger_cursor),0) FROM public.inventory_transactions) THEN
        RAISE EXCEPTION '0159 normal history changed during proof' USING ERRCODE='23514'; END IF;
    RETURN jsonb_build_object('stage','complete_supported_loss_history','root_disposition_id',checked_root::text,
        'observed_ledger_cursor',observed,
        'verified_original_ids',(SELECT COALESCE(jsonb_agg(value::text ORDER BY value),'[]'::jsonb) FROM unnest(visited) value),
        'verified_inverse_ids',(SELECT COALESCE(jsonb_agg(value::text ORDER BY value),'[]'::jsonb) FROM unnest(inverse_ids) value),
        'verified_correction_ids',(SELECT COALESCE(jsonb_agg(value::text ORDER BY value),'[]'::jsonb) FROM unnest(correction_ids) value));
END;
$function$

